<script setup lang="ts">
import { ref, computed, onMounted, nextTick } from 'vue';
import { useRoute } from 'vue-router';
import { UserPlus, Search, Pencil, Trash2, RefreshCw, X, Users, ArrowLeft, ArrowRight } from 'lucide-vue-next';
import { useApplication, errorMessage, roleLabel, statusLabel } from '../context';
import type { UserResponse } from '../../../application/dto/responses/user-responses';
const app = useApplication(); const route = useRoute(); const users = ref<UserResponse[]>([]); const search = ref(''); const status = ref(''); const busy = ref(false); const deleting = ref(false); const error = ref(''); const success = ref(''); const selected = ref<UserResponse | null>(null); const cancelButton = ref<HTMLButtonElement>(); const previousFocus = ref<HTMLElement | null>(null); const page = ref(1); const pageSize = 8;
const canRead = ['ADMIN', 'REVIEWER'].includes(app.currentSession()?.role || ''); const admin = app.currentSession()?.role === 'ADMIN';
const filtered = computed(() => users.value.filter(u => `${u.name} ${u.email} ${u.id}`.toLowerCase().includes(search.value.toLowerCase().trim()) && (!status.value || status.value === u.status)));
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize))); const currentPage = computed(() => Math.min(page.value, pages.value)); const visible = computed(() => filtered.value.slice((currentPage.value - 1) * pageSize, currentPage.value * pageSize));
async function load() { if (!canRead) return; busy.value = true; error.value = ''; try { users.value = await app.list(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load);
async function confirm(user: UserResponse) { previousFocus.value = document.activeElement as HTMLElement; selected.value = user; await nextTick(); cancelButton.value?.focus(); }
function close() { if (deleting.value) return; selected.value = null; previousFocus.value?.focus(); }
async function remove() { if (!selected.value) return; deleting.value = true; error.value = ''; try { await app.delete({ id: selected.value.id }); users.value = users.value.filter(u => u.id !== selected.value!.id); success.value = 'Usuario eliminado correctamente.'; deleting.value = false; close(); } catch (e) { error.value = errorMessage(e); } finally { deleting.value = false; } }
function trap(event: KeyboardEvent) { if (event.key !== 'Tab') return; const elements = Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button:not(:disabled)')); const first = elements[0]; const last = elements[elements.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } }
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">PERSONAS Y CONEXIONES</span><h1>{{ route.meta.mode === 'delete' ? 'Eliminar usuario' : route.meta.mode === 'edit' ? 'Editar usuario' : 'Tu equipo' }}<span class="heading-dot">.</span></h1><p class="muted">{{ route.meta.mode ? 'Encuentra a la persona que deseas gestionar.' : 'Las personas que hacen posible tu organización.' }}</p></div><RouterLink to="/usuarios/crear" class="button primary"><UserPlus :size="18"/>Crear usuario</RouterLink></div>
  <div v-if="error && !selected" class="error" role="alert">{{ error }}</div><div v-if="success" class="success" role="status">{{ success }}</div><div v-if="!canRead" class="notice">Tu rol no permite consultar usuarios. Solicita acceso a un administrador.</div>
  <section v-else class="panel"><div class="panel-heading"><h2>Directorio de usuarios <span class="count">{{ users.length }}</span></h2><button class="button secondary compact" :disabled="busy" @click="load"><RefreshCw :size="16"/>Actualizar</button></div><div class="filters"><div class="search-field"><Search :size="18"/><input v-model="search" aria-label="Buscar usuarios" placeholder="Buscar por nombre, correo o ID…" @input="page = 1"/></div><select v-model="status" aria-label="Filtrar por estado" @change="page = 1"><option value="">Todos los estados</option><option v-for="(label, key) in statusLabel" :key="key" :value="key">{{ label }}</option></select></div><p v-if="busy" class="empty" role="status">Cargando tu equipo…</p><div v-else-if="!visible.length" class="empty"><Users :size="35"/><h3>{{ error ? 'No se pudo cargar el equipo' : 'No hay usuarios para mostrar' }}</h3><p>{{ search || status ? 'Prueba con otros filtros.' : 'Crea un usuario para comenzar.' }}</p></div><div v-else class="table-scroll"><table><thead><tr><th>USUARIO</th><th>ROL</th><th>ESTADO</th><th>ACCIONES</th></tr></thead><tbody><tr v-for="user in visible" :key="user.id"><td><div class="user-cell"><span class="avatar">{{ user.name.slice(0, 2).toUpperCase() }}</span><div><strong>{{ user.name }}</strong><small>{{ user.email }}</small></div></div></td><td>{{ roleLabel[user.role] }}</td><td><span class="badge" :class="user.status.toLowerCase()"><i/>{{ statusLabel[user.status] }}</span></td><td><div class="row-actions"><RouterLink :to="`/usuarios/${encodeURIComponent(user.id)}/editar`" class="icon-button" :aria-label="`${admin ? 'Editar' : 'Ver'} ${user.name}`"><Pencil :size="17"/></RouterLink><button v-if="admin" class="icon-button danger-icon" :aria-label="`Eliminar ${user.name}`" @click="confirm(user)"><Trash2 :size="17"/></button></div></td></tr></tbody></table></div><div class="pagination"><span>{{ filtered.length }} usuarios · Página {{ currentPage }} de {{ pages }}</span><div><button class="icon-button" aria-label="Página anterior" :disabled="currentPage <= 1" @click="page = currentPage - 1"><ArrowLeft :size="17"/></button><button class="icon-button" aria-label="Página siguiente" :disabled="currentPage >= pages" @click="page = currentPage + 1"><ArrowRight :size="17"/></button></div></div></section>
  <Teleport to="body"><div v-if="selected" class="modal-overlay" @click.self="close" @keydown.esc="close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="delete-title" @keydown="trap"><button class="icon-button modal-close" aria-label="Cerrar" :disabled="deleting" @click="close"><X :size="20"/></button><span class="delete-icon"><Trash2 :size="26"/></span><h2 id="delete-title">¿Eliminar a {{ selected.name }}?</h2><p>Esta acción eliminará al usuario de la organización y no se puede deshacer.</p><div v-if="error" class="error" role="alert">{{ error }}</div><div class="form-actions"><button ref="cancelButton" class="button secondary" :disabled="deleting" @click="close">Cancelar</button><button class="button danger" :disabled="deleting" @click="remove">{{ deleting ? 'Eliminando…' : 'Eliminar usuario' }}</button></div></section></div></Teleport>
</template>
